#include "word_core.hpp"
int main(int argc,char**argv){if(argc<7){cerr<<"target certificate endpoints weight maxletter output\n";return 2;}auto start=chrono::steady_clock::now();auto sec=[&](){return chrono::duration<double>(chrono::steady_clock::now()-start).count();};string tf=argv[1],cf=argv[2],ef=argv[3],out=argv[6];int n=stoi(argv[4]),m=stoi(argv[5]);auto r=read_target(tf,n,-1);map<pair<int,int>,map<W,mpq_class>>endpoints;{ifstream f(ef);int n,bs;string c;while(f>>n>>bs>>c){vector<int>w(n);for(int&v:w)f>>v;mpq_class q(c);q.canonicalize();endpoints[{n,bs}][makew(w)]+=q;}}
 Fib fib;ifstream f(cf);string co;int count=0;while(f>>co){string context;f>>context;if(context!="0")throw runtime_error("nonempty context");U sc=read_label(f);mpq_class q(co);q.canonicalize();for(auto[w,c]:raw_source(sc,fib)){r[w]-=q*c;if(r[w]==0)r.erase(w);}if(!scaling_source(sc)){auto a=affdecode(sc);int bs=0;for(auto t:a)bs=bs*2+t.b;for(auto[w,c]:endpoints[{(int)a.size(),bs}]){r[w]+=q*c;if(r[w]==0)r.erase(w);}}if(++count%10000==0)cerr<<"APPLY "<<count<<" words="<<r.size()<<" secs="<<sec()<<"\n";}
 fib.cache.clear();Primitive p;map<W,mpq_class>res;int rw=0;for(auto[w,c]:r)if(maxw(w)==m){rw++;for(auto[v,d]:p.get(w))res[v]+=c*d;}for(auto it=res.begin();it!=res.end();)if(it->second==0)it=res.erase(it);else++it;
 cerr<<"CHECK primitive max="<<m<<" input_words="<<rw<<" residual="<<res.size()<<" seconds="<<sec()<<"\n";
 if(!res.empty()){save_target(out+".failed_projection",res);return 1;}
 save_target(out,r);ofstream report(out+".report.json");report<<"{\"weight\":"<<n<<",\"max_letter\":"<<m<<",\"certificate_rows\":"<<count<<",\"residual_primitive_terms\":0,\"remaining_full_words\":"<<r.size()<<",\"seconds\":"<<sec()<<",\"arithmetic\":\"GMP rational, complete unprojected sources\"}\n";return 0;
}
